module mad_calculator (input clk, input rst_n, input start, input [15:0] grid_data, input grid_valid, output reg [31:0] result, output reg done, output reg [5:0] state_out); reg [15:0] grid_array [4][4]; reg [2:0] state; reg [3:0] grid_counter; reg [3:0] grid_index; reg [1:0] r1, c1, r2, c2; reg [6:0] density_index; reg [15:0] densities [91]; reg [31:0] result_reg; reg done_reg; assign result = result_reg; assign done = done_reg; assign state_out = {3'b0, state}; parameter IDLE = 3'b000, LOAD = 3'b001, CALC_DENSITIES = 3'b010, SORT = 3'b011, MEDIAN = 3'b100, DONE = 3'b101; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; grid_counter <=0; grid_index <=0; r1 <=0; c1 <=0; r2 <=0; c2 <=0; density_index <=0; done_reg <=0; result_reg <=0; end else begin case(state) IDLE: if (start) begin state <= LOAD; grid_counter <=0; grid_index <=0; end LOAD: if (grid_valid) begin if (grid_counter <16) begin int row = grid_index /4; int col = grid_index %4; grid_array[row][col] <= grid_data; grid_index <= grid_index +1; grid_counter <= grid_counter +1; end else begin state <= CALC_DENSITIES; grid_index <=0; grid_counter <=0; end end end CALC_DENSITIES: begin if (r1 ==0 && c1==0 && r2==0 && c2==0) begin int area =1; int sum = grid_array[0][0]; int density = sum / area; densities[density_index] <= density; density_index <= density_index +1; c2 <=1; end else if (c2 <3) begin c2 <= c2 +1; end else begin c2 <=0; c1 <= c1 +1; if (c1 ==4) begin c1 <=0; r1 <= r1 +1; if (r1 ==4) begin state <= SORT; end end end end end SORT: state <= MEDIAN; MEDIAN: begin int median = densities[0]; result_reg <= {16'b0, median}; done_reg <=1; state <= DONE; end DONE: endcase end end endmodule